void counting_sort(int A[], int length)

{



int i; int frequency[10]; int *SortedArray;



for(i=0;i<10;i++)



{frequency[i]=0;}



SortedArray=(int *)calloc(length,sizeof(int));



for(i=0;i<length;i++)



{SortedArray[i]=-3;}



